let crmAuthRefreshFlightV236166=null;
function crmJwtExpiredV236166(err){
  const msg=String(err?.message||err?.error_description||err?.details||err||'');
  const code=String(err?.code||'');
  const status=Number(err?.status||err?.statusCode||0);
  return /jwt\s*expired|token\s*expired|expired\s*jwt/i.test(msg)
    || code==='PGRST303'
    || (status===401&&/jwt|token/i.test(msg));
}
async function crmEnsureFreshSessionV236166(force=false){
  if(crmAuthRefreshFlightV236166)return crmAuthRefreshFlightV236166;
  crmAuthRefreshFlightV236166=(async()=>{
    const {data,error}=await db.auth.getSession();
    if(error)throw error;
    const session=data?.session;
    if(!session)throw new Error('Сессия CRM завершена. Войдите снова.');
    const now=Math.floor(Date.now()/1000),exp=Number(session.expires_at||0);
    if(!force&&exp>now+90)return session;
    const refreshed=await db.auth.refreshSession();
    if(refreshed.error||!refreshed.data?.session){
      throw refreshed.error||new Error('Не удалось обновить сессию CRM');
    }
    currentUser=refreshed.data.session.user||currentUser;
    return refreshed.data.session;
  })().finally(()=>{crmAuthRefreshFlightV236166=null});
  return crmAuthRefreshFlightV236166;
}
async function crmAuthRetryV236166(factory){
  let result=await factory();
  if(result?.error&&crmJwtExpiredV236166(result.error)){
    await crmEnsureFreshSessionV236166(true);
    result=await factory();
  }
  return result;
}
window.crmEnsureFreshSessionV236166=crmEnsureFreshSessionV236166;
window.crmAuthRetryV236166=crmAuthRetryV236166;

let crmLoginFlightV236258=null;
let crmFreshSessionV236258=null;
let crmFreshSessionUntilV236258=0;
let crmExplicitSignOutV236258=false;

function crmShowSignedOutUiV236258(){
  currentUser=null; currentProfile=null;
  const login=document.getElementById('login-wrap');
  const app=document.getElementById('app');
  if(login)login.style.display='flex';
  if(app)app.style.display='none';
}

async function crmLocalSignOutV236258(){
  crmExplicitSignOutV236258=true;
  crmFreshSessionV236258=null;
  crmFreshSessionUntilV236258=0;
  try{return await db.auth.signOut({scope:'local'});}
  finally{setTimeout(()=>{crmExplicitSignOutV236258=false;},500);}
}

async function crmRecoverFreshSessionV236258(){
  if(crmExplicitSignOutV236258||Date.now()>crmFreshSessionUntilV236258)return null;
  let session=null;
  try{session=(await db.auth.getSession()).data?.session||null;}catch(_){}
  if(session?.user)return session;
  const fresh=crmFreshSessionV236258;
  if(!fresh?.access_token||!fresh?.refresh_token)return null;
  try{
    const restored=await db.auth.setSession({
      access_token:fresh.access_token,
      refresh_token:fresh.refresh_token
    });
    if(!restored.error&&restored.data?.session)return restored.data.session;
  }catch(_){}
  return null;
}

async function doLogin() {
  // На Android Enter + tap (или двойной tap WebView) раньше могли запустить два
  // signInWithPassword одновременно. Это создаёт две сессии и оставляет старый
  // refresh-поток конкурировать с новой сессией. Разрешаем только один login-flight.
  if(crmLoginFlightV236258)return crmLoginFlightV236258;
  crmLoginFlightV236258=(async()=>{
    const email = document.getElementById('login-email').value.trim().toLowerCase();
    const pass = document.getElementById('login-pass').value;
    const err = document.getElementById('login-error');
    const btn = document.getElementById('login-btn');
    err.style.display='none';
    if (!email||!pass){err.textContent='Введите email и пароль';err.style.display='block';return;}
    btn.disabled=true; btn.textContent='Входим...';

    // Останавливаем старый refresh-таймер WebView и локально очищаем только эту
    // вкладку/приложение. Глобальный signOut здесь запрещён: он отзывает сессии
    // пользователя на других устройствах.
    try{db.auth.stopAutoRefresh();}catch(_){}
    crmExplicitSignOutV236258=true;
    try{await db.auth.signOut({scope:'local'});}catch(_){}
    crmExplicitSignOutV236258=false;

    try{
      const {data,error} = await withTimeout(
        db.auth.signInWithPassword({email,password:pass}), 20000, 'вход в систему'
      );
      if (error){
        err.textContent='Неверный email или пароль';err.style.display='block';return;
      }
      currentUser = data.user;
      crmFreshSessionV236258=data.session||null;
      crmFreshSessionUntilV236258=Date.now()+12000;
      try{db.auth.startAutoRefresh();}catch(_){}
      await loadProfileAndStart();
      // После стабильного старта свежий refresh-token больше в guard не нужен.
      setTimeout(()=>{
        if(Date.now()>=crmFreshSessionUntilV236258)crmFreshSessionV236258=null;
      },13000);
    }catch(e){
      console.error('doLogin failed',e);
      err.textContent='Сервер не отвечает. Проверьте интернет и попробуйте снова.';
      err.style.display='block';
    }finally{
      try{db.auth.startAutoRefresh();}catch(_){}
      btn.disabled=false; btn.textContent='Войти';
    }
  })().finally(()=>{crmLoginFlightV236258=null;});
  return crmLoginFlightV236258;
}

async function doLogout() {
  document.body.classList.remove('crm-auditor-mode');
  await crmLocalSignOutV236258();
  crmShowSignedOutUiV236258();
}

async function loadProfileAndStart() {
  try {
    const email=String(currentUser?.email||'').trim().toLowerCase();
    const loadProfile=()=>db.from('users').select('*').eq('email',email).maybeSingle();
    let result=null;
    for(const delay of [0,500,1400]){
      if(delay)await new Promise(r=>setTimeout(r,delay));
      result=await crmAuthRetryV236166(loadProfile);
      if(!result?.error)break;
    }
    const {data:profile,error}=result||{};
    if(error) throw error;
    if(!profile){
      // SECURITY: подтверждённое отсутствие активного CRM-профиля — реальный logout.
      await crmLocalSignOutV236258().catch(()=>{});
      currentUser=null;currentProfile=null;
      document.getElementById('login-wrap').style.display='flex';
      document.getElementById('app').style.display='none';
      const err=document.getElementById('login-error');
      if(err){err.textContent='Доступ к CRM отключён. Обратитесь к руководителю.';err.style.display='block';}
      return;
    }
    currentProfile=profile;
    // Company leadership gets its own server-scoped read-only portal.
    // Never run the broad manager/boss bootstrap for this role.
    if(String(profile.role||'').toLowerCase()==='executive_viewer'){
      if(!window.crmCompanyViewer360?.start){
        document.getElementById('app').style.display='none';
        document.getElementById('login-wrap').style.display='flex';
        const e=document.getElementById('login-error');
        if(e){e.style.display='block';e.textContent='Руководящий режим временно недоступен. Обновите страницу.';}
        return;
      }
      await window.crmCompanyViewer360.start(profile);
      return;
    }
    // Auditors use the NORMAL CRM login, never an independent website.
    // The warehouse shell skips sales, clients, GPS and other CRM bootstrap.
    if(['auditor','auditor_pending'].includes(String(profile.role||'').toLowerCase())){
      await crmStartAuditorWarehouseV1();
      return;
    }
    startApp();
  } catch(e) {
    // v23.6.257: временный обрыв сети/проверки профиля больше не уничтожает
    // действующую Supabase-сессию. Менеджеру не надо заново вводить пароль.
    console.error('Profile load failed; session preserved',e);
    let session=null;
    try{session=(await db.auth.getSession()).data?.session||null;}catch(_){}
    if(session?.user)currentUser=session.user;
    if(currentProfile){
      document.getElementById('login-wrap').style.display='none';
      document.getElementById('app').style.display='flex';
      return;
    }
    document.getElementById('login-wrap').style.display='flex';
    document.getElementById('app').style.display='none';
    const err=document.getElementById('login-error');
    if(err){
      err.textContent='Связь с CRM временно прервалась. Сессия сохранена — проверьте интернет и откройте приложение ещё раз, пароль вводить не нужно.';
      err.style.display='block';
    }
  }
}

async function initAuth(){
  // Recovery URLs must never bootstrap sales, GPS or warehouse before the
  // PASSWORD_RECOVERY event has verified the one-time link.
  if(crmIsRecoveryUrlV1()){
    document.getElementById('login-wrap').style.display='flex';
    const info=document.getElementById('login-info');
    if(info){info.textContent='Проверяем ссылку для смены пароля…';info.style.display='block'}
    return;
  }
  const {data:{session}} = await db.auth.getSession();
  if(session && session.user){
    currentUser=session.user;
    await loadProfileAndStart();
    return;
  }
  document.getElementById('login-wrap').style.display='flex';
}

function crmHandleAuthEventV20261105(event,session){
  if(event==='PASSWORD_RECOVERY'){
    // Defer user interaction until the auth callback returns: no auth calls
    // inside the onAuthStateChange handler (prevents session deadlock).
    setTimeout(crmShowPasswordRecoveryV1,0);
    return;
  }
  if(event==='SIGNED_OUT'){
    // Android WebView может прислать поздний SIGNED_OUT от старого refresh-потока
    // уже после успешного нового входа. Серверная свежая сессия при этом жива.
    if(!crmExplicitSignOutV236258&&Date.now()<=crmFreshSessionUntilV236258&&crmFreshSessionV236258){
      setTimeout(async()=>{
        const session=await crmRecoverFreshSessionV236258();
        if(session?.user){
          currentUser=session.user;
          if(!currentProfile)await loadProfileAndStart();
          return;
        }
        crmShowSignedOutUiV236258();
      },180);
      return;
    }
    crmShowSignedOutUiV236258();
  }
}

